exactSources.calcReadiness:
function calcReadiness(){
  const c=readinessComponents();
  // FE QUEST独自の「受験準備の仕上がり」指標。合格確率ではない。
  const raw=c.lesson*.25 + c.aPractice*.20 + c.aMock*.20 + c.bTraining*.15 + c.bExam*.15 + c.memoryEvidence*.05;
  return Math.round(clamp(raw,0,100));
}

exactSources.readinessComponents:
function readinessComponents(){
  const lesson=lessonCompletionAverage();
  const skillVals=sortedSkills().map(x=>x[1]);
  const skill=skillVals.length?Math.round(skillVals.reduce((a,b)=>a+b,0)/skillVals.length):0;
  const quiz=recentQuizRate();
  const cognitive=subjectACognitiveEvidence();
  const aPractice=Math.round(skill*.35 + quiz*.30 + cognitive*.35);

  const fullMocks=(profile.mockHistory||[]).filter(x=>x.mode==='full');
  const halfMocks=(profile.mockHistory||[]).filter(x=>x.mode==='half');
  const aMock=fullMocks.length?recentAverageRate(fullMocks,3):Math.round(recentAverageRate(halfMocks,2)*.8);

  const bAlgo=objectCompletion(profile.bProgress,B_EXERCISES.length);
  const bSec=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
  const bTraining=Math.round((bAlgo+bSec)/2);
  const bExam=recentAverageRate(profile.bFinalHistory||[],3);

  const mem=memoryHealth();
  const memoryEvidence=mem.attempted?Math.round(mem.avg*Math.min(1,mem.attempted/60)):0;

  return {lesson,aPractice,aMock,bTraining,bExam,memoryEvidence,cognitive};
}

exactSources.subjectACognitiveEvidence:
function subjectACognitiveEvidence(){
  const rows=QUESTION_BANK.map(q=>({q,st:profile.qStats?.[q.id]})).filter(x=>(x.st?.attempts||0)>0);
  if(!rows.length)return 0;
  let weighted=0,denom=0;
  rows.forEach(({q,st})=>{
    const accuracy=st.attempts?clamp((st.correct||0)/st.attempts*100,0,100):0;
    const retention=memoryRetention(st)??accuracy;
    const score=accuracy*.60+retention*.40;
    const w=cognitiveWeight(q);
    weighted+=score*w;denom+=w;
  });
  const coverageWeight=rows.reduce((n,x)=>n+cognitiveWeight(x.q),0);
  const totalWeight=QUESTION_BANK.reduce((n,q)=>n+cognitiveWeight(q),0);
  const coverage=totalWeight?coverageWeight/totalWeight:0;
  return Math.round((weighted/Math.max(1,denom))*(.60+.40*coverage));
}

exactSources.categoryCognitiveEvidence:
function categoryCognitiveEvidence(cat){
  const levels=['想起','適用','判断'].map(level=>cognitiveLevelEvidence(cat,level));
  const prior=Math.round(profile.skills?.[cat]||50);
  const tested=levels.filter(x=>x.score!=null);
  const denom=levels.reduce((s,x)=>s+COGNITIVE_WEIGHTS[x.level],0);
  const weighted=levels.reduce((s,x)=>s+(x.score==null?prior:x.score)*COGNITIVE_WEIGHTS[x.level],0);
  const score=tested.length?Math.round(weighted/Math.max(1,denom)):prior;
  const weakest=[...levels].sort((a,b)=>{
    const as=a.score==null?50:a.score,bs=b.score==null?50:b.score;
    if(as!==bs)return as-bs;
    return COGNITIVE_WEIGHTS[b.level]-COGNITIVE_WEIGHTS[a.level];
  })[0];
  return {cat,score,levels,weakest};
}

exactSources.cognitiveLevelEvidence:
function cognitiveLevelEvidence(cat,level){
  ensureQuestionProfile();
  const qs=QUESTION_BANK.filter(q=>q.cat===cat&&q.cognitiveLevel===level);
  const attempted=qs.filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0);
  const attempts=attempted.reduce((n,q)=>n+(profile.qStats[q.id].attempts||0),0);
  const correct=attempted.reduce((n,q)=>n+(profile.qStats[q.id].correct||0),0);
  const accuracy=attempts?Math.round(correct/attempts*100):null;
  const ret=attempted.map(q=>memoryRetention(profile.qStats[q.id])).filter(x=>x!=null);
  const retention=ret.length?Math.round(ret.reduce((a,b)=>a+b,0)/ret.length):null;
  const raw=accuracy==null?null:Math.round(accuracy*.65+(retention??accuracy)*.35);
  const coverage=qs.length?Math.round(attempted.length/qs.length*100):0;
  const score=raw==null?null:Math.round(raw*(.72+.28*coverage/100));
  return {level,total:qs.length,attempted:attempted.length,attempts,correct,accuracy,retention,coverage,score};
}

exactSources.courseMasteryStatus:
function courseMasteryStatus(){
  ensureChapterMasteryProfile();
  const topicStates=CORE_A_CURRICULUM.map(t=>({topic:t,state:coreTopicLearningState(t.id)}));
  syncMasteryRecoveryHistory(topicStates);
  const recovering=topicStates.filter(x=>!!masteryRecoveryInfo(x.topic.id)).length;
  const master=topicStates.filter(x=>x.state.key==='master').length;
  const stable=topicStates.filter(x=>['stable','master'].includes(x.state.key)).length;
  const lessonDone=CORE_A_CURRICULUM.filter(t=>(profile.lessonProgress?.[t.id]||0)>=100).length;
  const chapterPassed=CORE_A_CHAPTERS.filter(ch=>chapterIntegrationEvidence(ch).passed).length;

  const skillRows=sortedSkills();
  const weakest=skillRows[0]||['アルゴリズム',0];
  const mem=memoryHealth();

  const fullMocks=(profile.mockHistory||[]).filter(x=>x.mode==='full');
  const aMock=recentConsistency(fullMocks,2,75,70);
  const bFinal=recentConsistency(profile.bFinalHistory||[],2,70,65);

  const bAlgo=objectCompletion(profile.bProgress,B_EXERCISES.length);
  const bSec=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
  const bTraining=Math.round((bAlgo+bSec)/2);

  const gates=[
    {id:'lesson',name:'科目A教材',passed:lessonDone===CORE_A_CURRICULUM.length,value:`${lessonDone}/${CORE_A_CURRICULUM.length}`},
    {id:'topics',name:'テーマ定着',passed:stable>=117,value:`${stable}/130（習得 ${master}）`},
    {id:'chapters',name:'章末統合',passed:chapterPassed===21,value:`${chapterPassed}/21`},
    {id:'weak',name:'最低分野習熟',passed:Number(weakest[1])>=70,value:`${weakest[0]} ${Math.round(weakest[1])}%`},
    {id:'memory',name:'復習定着',passed:mem.attempted>0&&mem.avg>=85&&mem.due<=10,value:`保持 ${mem.avg}%・要復習 ${mem.due}`},
    {id:'bTraining',name:'科目B学習',passed:bTraining>=90,value:`${bTraining}%`},
    {id:'aMock',name:'科目Aフル模試',passed:aMock.passed,value:aMock.count>=2?`直近2回 平均${aMock.avg}%・最低${aMock.min}%`:`${aMock.count}/2回`},
    {id:'bFinal',name:'科目B総合実戦',passed:bFinal.passed,value:bFinal.count>=2?`直近2回 平均${bFinal.avg}%・最低${bFinal.min}%`:`${bFinal.count}/2回`}
  ];

  return {
    topicStates,master,recovering,stable,lessonDone,chapterPassed,weakest,mem,bTraining,aMock,bFinal,gates,
    passed:gates.filter(g=>g.passed).length,
    ready:gates.every(g=>g.passed)
  };
}

exactSources.memoryHealth:
function memoryHealth(){
  ensureQuestionProfile();
  const attempted=trackedQuestionPool()
    .map(q=>({q,st:profile.qStats[q.id]}))
    .filter(x=>x.st?.attempts>0);
  if(!attempted.length) return {attempted:0,avg:100,fresh:0,soon:0,due:0};
  const rows=attempted.map(x=>({...x,retention:memoryRetention(x.st),weight:cognitiveWeight(x.q)}));
  const denom=rows.reduce((s,x)=>s+x.weight,0);
  const avg=Math.round(rows.reduce((s,x)=>s+(x.retention??100)*x.weight,0)/Math.max(1,denom));
  return {
    attempted:rows.length,
    avg,
    fresh:rows.filter(x=>(x.retention??100)>=93).length,
    soon:rows.filter(x=>(x.retention??100)<93 && (x.retention??100)>=80).length,
    due:rows.filter(x=>isDue(x.st) || (x.retention??100)<80).length
  };
}

exactSources.examAreaProgress:
function examAreaProgress(area){
  if(area.special==='b'){
    const a=objectCompletion(profile.bProgress,B_EXERCISES.length);
    const s=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
    return Math.round((a+s)/2);
  }
  const valid=(area.ids||[]).filter(id=>LESSONS[id]);
  if(!valid.length) return 0;
  return Math.round(valid.reduce((sum,id)=>sum+(profile.lessonProgress?.[id]||0),0)/valid.length);
}

exactSources.renderReadiness:
function renderReadiness(){
  const r=calcReadiness();
  const ring=document.getElementById('readinessRing');
  if(ring) ring.style.setProperty('--p',r);
  if(document.getElementById('readinessValue')) document.getElementById('readinessValue').textContent=r+'%';
  if(document.getElementById('rightReadiness')) document.getElementById('rightReadiness').textContent=r+'%';
  if(document.getElementById('rightReadinessBar')) document.getElementById('rightReadinessBar').style.width=r+'%';

  let label='基礎づくり中';
  if(r>=80) label='総仕上げへ進める状態';
  else if(r>=65) label='実戦力を伸ばす段階';
  else if(r>=45) label='主要分野を定着中';
  else if(r>=25) label='基礎を広げている段階';
  if(document.getElementById('readinessLabel')) document.getElementById('readinessLabel').textContent=label;

  const c=readinessComponents();
  const breakdown=document.getElementById('readinessBreakdown');
  if(breakdown){
    const rows=[
      ['科目A教材',c.lesson],['科目A演習',c.aPractice],['科目A模試',c.aMock],
      ['科目B学習',c.bTraining],['科目B総合',c.bExam],['復習定着',c.memoryEvidence]
    ];
    breakdown.innerHTML=rows.map(([name,val])=>`<div class="readiness-part"><span>${name}</span><b>${val}%</b></div>`).join('');
  }

  const weak=weakestSkill();
  const focus=`現在は「${weak}」を優先。`;
  if(document.getElementById('rightFocus')) document.getElementById('rightFocus').textContent=focus;
  if(document.getElementById('adaptiveNote')){
    const routes=actionableReviewJourneys().length,due=dueQuestions().length;
    const reviewText=routes
      ? ` 誤答から続いている復習ルートが${routes}件あります。まず「教材→類題→後日確認」の続きから進めます。`
      : due
        ? ` 復習期限の問題が${due}問あります。まず復習から始めるのがおすすめです。`
        : ' 復習待ちはないので、新しい教材を進めて構いません。';
    document.getElementById('adaptiveNote').innerHTML=`<b>FE QUESTの提案：</b> ${focus}${reviewText}`;
  }
  renderFinalMasterPanel();
}

exactSources.mockAttemptDiagnostics:
function mockAttemptDiagnostics(details,byCat){
  const target=mockTargetSeconds();
  const wrongRows=details.filter(d=>d.answerIndex===null||d.answerIndex!==d.correctIndex);
  const slowRows=details.filter(d=>(d.seconds||0)>target*1.35);
  const repeatRows=wrongRows.filter(d=>(profile.mockMistakeStats?.[d.id]?.misses||0)>=1);
  const weakest=Object.entries(byCat||{}).filter(([,v])=>v.total).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total))[0];
  return {target,wrong:wrongRows.length,slow:slowRows.length,repeat:repeatRows.length,weakest:weakest?{cat:weakest[0],pct:Math.round(weakest[1].correct/weakest[1].total*100)}:null};
}

exactSources.examStudyPhase:
function examStudyPhase(days=examDaysRemaining()){
  if(days==null)return {id:'normal',name:'通常学習',icon:'📘',ratios:{review:.17,lesson:.33,subjectB:.33,boss:.17},allowNew:true,allowLongExam:true};
  if(days<0)return {id:'expired',name:'受験日経過',icon:'📅',ratios:{review:.17,lesson:.33,subjectB:.33,boss:.17},allowNew:true,allowLongExam:true};
  if(days>90)return {id:'foundation',name:'基礎拡張期',icon:'🌱',ratios:{review:.15,lesson:.35,subjectB:.30,boss:.20},allowNew:true,allowLongExam:true};
  if(days>30)return {id:'build',name:'実力形成期',icon:'🧩',ratios:{review:.20,lesson:.25,subjectB:.35,boss:.20},allowNew:true,allowLongExam:true};
  if(days>14)return {id:'finish',name:'仕上げ期',icon:'🎯',ratios:{review:.25,lesson:.15,subjectB:.35,boss:.25},allowNew:true,allowLongExam:true};
  if(days>7)return {id:'finalPractice',name:'直前演習期',icon:'🏁',ratios:{review:.30,lesson:.10,subjectB:.30,boss:.30},allowNew:true,allowLongExam:true};
  if(days>3)return {id:'taper',name:'直前調整期',icon:'🧠',ratios:{review:.35,lesson:.25,subjectB:.20,boss:.20},allowNew:true,allowLongExam:true};
  if(days>1)return {id:'protect',name:'仕上がり保護期',icon:'🛡️',ratios:{review:.40,lesson:.40,subjectB:0,boss:.20},allowNew:false,allowLongExam:false};
  if(days===1)return {id:'eve',name:'前日確認',icon:'🌙',ratios:{review:.67,lesson:0,subjectB:0,boss:.33},allowNew:false,allowLongExam:false};
  return {id:'examDay',name:'受験当日',icon:'☀️',ratios:{review:0,lesson:0,subjectB:0,boss:1},allowNew:false,allowLongExam:false};
}
